#include <stdio.h>
#include <math.h>
#include <stdlib.h>

typedef struct { float x, y, z; } V;
typedef struct { V o, d; } R;
typedef struct { float t; V p, n; int hit; } H;

static V vadd(V a, V b) { return (V){a.x+b.x, a.y+b.y, a.z+b.z}; }
static V vsub(V a, V b) { return (V){a.x-b.x, a.y-b.y, a.z-b.z}; }
static V vmul(V a, float s) { return (V){a.x*s, a.y*s, a.z*s}; }
static float vdot(V a, V b) { return a.x*b.x + a.y*b.y + a.z*b.z; }
static V vnorm(V a) {
    float l = (float)sqrt((double)vdot(a, a));
    return (V){a.x/l, a.y/l, a.z/l};
}
static R ray(V o, V d) { R r; r.o = o; r.d = vnorm(d); return r; }
static V at(R r, float t) { return vadd(r.o, vmul(r.d, t)); }

static H sph(R r, V c, float rad) {
    H h = {0};
    V oc = vsub(r.o, c);
    float a = vdot(r.d, r.d);
    float b = 2.0f * vdot(r.d, oc);
    float cc = vdot(oc, oc) - rad*rad;
    float disc = b*b - 4.0f*a*cc;
    if (disc < 0.0f) return h;
    float t = (-b - (float)sqrt((double)disc)) / (2.0f*a);
    if (t < 0.001f) {
        t = (-b + (float)sqrt((double)disc)) / (2.0f*a);
        if (t < 0.001f) return h;
    }
    h.t = t;
    h.p = at(r, t);
    h.n = vnorm(vsub(h.p, c));
    h.hit = 1;
    return h;
}

static H plane(R r, float py) {
    H h = {0};
    if (fabsf(r.d.y) < 0.0001f) return h;
    float t = (py - r.o.y) / r.d.y;
    if (t < 0.001f) return h;
    h.t = t;
    h.p = at(r, t);
    h.n = (V){0, 1, 0};
    h.hit = 1;
    return h;
}

static int shadow(R r, V c, float rad) {
    return sph(r, c, rad).hit;
}

static V sky(R r) {
    float t = 0.5f * (r.d.y + 1.0f);
    V a = {1, 1, 1};
    V b = {0.5f, 0.7f, 1.0f};
    return vadd(vmul(a, 1.0f - t), vmul(b, t));
}

static V trace(R r, V sc, float sr, V light) {
    H hs = sph(r, sc, sr);
    H hp = plane(r, -1.5f);
    H h;
    int type;
    if (hs.hit) {
        if (hp.hit && hp.t <= hs.t) { h = hp; type = 0; }
        else { h = hs; type = 1; }
    } else if (hp.hit) { h = hp; type = 0; }
    else return sky(r);

    float diff = vdot(h.n, light);
    if (diff < 0) diff = 0;
    R sh = ray(vadd(h.p, vmul(h.n, 0.001f)), light);
    if (shadow(sh, sc, sr)) diff = 0;
    float ambient = 0.2f;
    float inten = ambient + (1.0f - ambient) * diff;

    if (type == 1) {
        V c = {1.0f, 0.2f, 0.2f};
        return vmul(c, inten);
    } else {
        int ch = ((int)(floor(h.p.x) + floor(h.p.z))) & 1;
        float g = ch == 0 ? 0.9f : 0.4f;
        V c = {g, g, g};
        return vmul(c, inten);
    }
}

int main(void) {
    int w = 2400, h = 1800;
    V sc = {0, -0.5f, -5};
    float sr = 1.0f;
    V light = vnorm((V){1, 1, -1});
    float aspect = (float)w / (float)h;
    FILE *f = fopen("reconstructed.ppm", "w");
    fprintf(f, "P3\n%d %d\n255\n", w, h);
    int i, j;
    for (j = 0; j < h; j++) {
        float v = (float)j / (float)(h - 1);
        for (i = 0; i < w; i++) {
            float u = (float)i / (float)(w - 1);
            V d = {aspect * (2.0f*u - 1.0f), 1.0f - 2.0f*v, -1.0f};
            V col = trace(ray((V){0, 0, 0}, d), sc, sr, light);
            float r = col.x, g = col.y, b = col.z;
            if (r < 0) r = 0; if (r > 1) r = 1;
            if (g < 0) g = 0; if (g > 1) g = 1;
            if (b < 0) b = 0; if (b > 1) b = 1;
            fprintf(f, "%d %d %d\n", (int)(r*255.99f), (int)(g*255.99f), (int)(b*255.99f));
        }
    }
    fclose(f);
    return 0;
}

